CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL CHECK(email=lower(email)),password TEXT NOT NULL,role VARCHAR(10) NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS store_categories (id SERIAL PRIMARY KEY,name VARCHAR(60) UNIQUE NOT NULL,icon VARCHAR(30) NOT NULL DEFAULT 'box',sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS products (id SERIAL PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT NOT NULL,category VARCHAR(60) NOT NULL REFERENCES store_categories(name) ON UPDATE CASCADE,price_cents INTEGER NOT NULL CHECK(price_cents>=0),image TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),active BOOLEAN NOT NULL DEFAULT TRUE,featured BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS store_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS store_payments (id SERIAL PRIMARY KEY,code VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,instructions TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS shop_orders (id SERIAL PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),checkout_key UUID UNIQUE NOT NULL,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL,address VARCHAR(500) NOT NULL,city VARCHAR(100) NOT NULL,postal VARCHAR(30) NOT NULL,country VARCHAR(80) NOT NULL,total_cents INTEGER NOT NULL CHECK(total_cents>=0),shipping_cents INTEGER NOT NULL CHECK(shipping_cents>=0),currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','shipped','completed','cancelled')),payment_method VARCHAR(30) NOT NULL,payment_name VARCHAR(80) NOT NULL,payment_instructions TEXT NOT NULL DEFAULT '',payment_status VARCHAR(20) NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid','refunded')),payment_reference VARCHAR(120) NOT NULL DEFAULT '',tracking_number VARCHAR(160) NOT NULL DEFAULT '',admin_notes TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS shop_order_items (id SERIAL PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES shop_orders(id),product_id INTEGER NOT NULL REFERENCES products(id),name VARCHAR(160) NOT NULL,price_cents INTEGER NOT NULL CHECK(price_cents>=0),quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE INDEX IF NOT EXISTS order_user_idx ON shop_orders(user_id);
CREATE INDEX IF NOT EXISTS order_item_idx ON shop_order_items(order_id);
CREATE TABLE IF NOT EXISTS auth_attempts (key TEXT PRIMARY KEY,attempts INTEGER NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
